const THEME_KEY = "infoDarkMode"

export function getTheme(callback) {
  storage.get({
    key: THEME_KEY,
    success: function (data) {
      callback(data === "true")
    },
    fail: function () {
      callback(false)
    }
  })
}

export function setTheme(isDark) {
  storage.set({
    key: THEME_KEY,
    value: isDark ? "true" : "false"
  })
}

