import storage from "@system.storage"

const THEME_KEY = "infoDarkMode"
var cachedTheme = null

export function getThemeSync() {
  return cachedTheme !== null ? cachedTheme : false
}

export function getTheme(callback) {
  if (cachedTheme !== null) {
    callback(cachedTheme)
    return
  }
  storage.get({
    key: THEME_KEY,
    success: function (data) {
      cachedTheme = data === "true"
      callback(cachedTheme)
    },
    fail: function () {
      cachedTheme = false
      callback(false)
    }
  })
}

export function setTheme(isDark) {
  cachedTheme = isDark
  storage.set({
    key: THEME_KEY,
    value: isDark ? "true" : "false"
  })
}

var store = {}

export function getCached(key) {
  var entry = store[key]
  if (!entry) return null
  if (Date.now() > entry.expireAt) {
    delete store[key]
    return null
  }
  return entry.value
}

export function setCache(key, value, ttlMs) {
  store[key] = {
    value: value,
    expireAt: Date.now() + ttlMs
  }
}

